mapper.select:
select * from ( SELECT T1.ISSUE_AMT/10000 ISSUE_AMT,
,T2.IS_SEC_BOND
,T6.INT_TYPE AS rateType ,nvl(T8.YIELD, T6.RATE)*100 RATE ,T4.TYPE_4 ,T4.TYPE_5
,T4.TYPE_9 ,T4.TYPE_10 ,T4.TYPE_11 ,T4.TYPE_12
,T6.COEFFICIENT ,T6.SPREAD_RATE*100 SPREAD_RATE
,T6.BENCHMARK_ID as indexId ,T7.PARTY_TYPE2 ,T8.BASIS ,T9.PAY_CYCLE payCycle ,MST_CUSTOMER_INFO.CUSTOMER_NAME issuerName ,MST_CUSTOMER_INFO.CUSTOMER_ID issuer ,B.EXERCISE_DATE exerciseDate ,T2.IS_CITY_BOND isCityBond ,T2.IS_ISSUE_ASSET isIssueAsset ,T2.APPEAR_MARKET_ID appearMarketId ,T7.INDUSTRY industry ,T7.INDUSTRY2 industry2 ,T2.IS_PPB isPPb, T2.IS_NETPRICE isNetprice, T2.IS_NET_SETT isNetSett, T2.IS_NO_GUARD isNoGuard FROM FIN_PRODUCT T1 LEFT JOIN MST_CUSTOMER_INFO ON MST_CUSTOMER_INFO.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T3.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_INFO T5 ON T5.FINPROD_ID = T1.FINPROD_ID
AND T5.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T5.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T6 ON T6.CASH_ID = T5.CASH_ID AND T6.EFF_DATE = T1.VDATE left join (select FINPROD_ID, max(eff_date) as EFF_DATE from FIN_CASH_CALC_RULE group by FINPROD_ID ) tempT8 on T1.FINPROD_ID = tempT8.FINPROD_ID
LEFT JOIN FIN_CASH_CALC_RULE T8 ON T8.FINPROD_ID=tempT8.FINPROD_ID AND T8.EFF_DATE = tempT8.EFF_DATE and T8.CASH_ID = T5.CASH_ID LEFT JOIN MST_CUSTOMER_INFO_ADD T7 ON T7.CUSTOMER_ID = T3.CUSTOMER_ID LEFT JOIN FIN_CASH_PAY_RULE T9 ON T9.CASH_ID = T8.CASH_ID AND T8.EFF_DATE = T9.EFF_DATE LEFT JOIN (select A.FINPROD_ID,max(A.EXERCISE_DATE) EXERCISE_DATE from FIN_EXERCISE_PLAN A group by A.FINPROD_ID) B on T1.FINPROD_ID = B.FINPROD_ID) T
AND (T.FINPROD_MARKET_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%') or T.FINPROD_NAME like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%'))
AND T.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T.CCY = #{ccy,jdbcType=VARCHAR}
AND T.TYPE_4 in
#{item}
AND T.TYPE_5 = #{type5,jdbcType=VARCHAR}
AND T.TYPE_9 in
#{item}
AND T.TYPE_10 in
#{item}
AND T.TYPE_11 in
#{item}
AND T.rateType = #{rateType,jdbcType=VARCHAR}
AND T.COUPON_SPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND T.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND T.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND T.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND T.ISSUER = #{issuer,jdbcType=VARCHAR}
AND T.ISISSUEASSET = #{isIssueAsset,jdbcType=VARCHAR}
AND (T.ISISSUEASSET = #{isIssueAsset,jdbcType=VARCHAR} OR T.ISISSUEASSET IS NULL)
and T.FINPROD_ID in ( select FINPROD_ID from ( select FINPROD_ID,min(TRADE_DATE) from TRD_PRODUCT_DEAL where TRADE_DATE = to_date(#{platDate,jdbcType=VARCHAR},'yyyy-mm-dd') and IS_OUT_TRADE = 'Y' and FINPROD_TYPE2 = 'F01' and IS_CANCEL = 'N' and TRADE_STATUS = '01' group by FINPROD_ID having min(TRADE_DATE) = to_date(#{platDate,jdbcType=VARCHAR},'yyyy-mm-dd') ) )

SELECT FINPROD_ID id, FINPROD_ABBR||':'||FINPROD_MARKET_ID text FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND ( FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND FINPROD_ID = #{initValue}
AND FINPROD_ID NOT IN( SELECT O_FINPROD_ID FROM FIN_PRODUCT WHERE O_FINPROD_ID IS NOT NULL )

SELECT count(1)
FROM FIN_PRODUCT
WHERE O_FINPROD_ID = #{oFinprodId}
and FINPROD_ID != #{finprodId}

mapper.delete:
delete from PA_TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

	and FINPROD_TYPE2 = #{finProdType2}

)

delete from TRD_FIN_PRODUCT_DEAL_TOTAL tfpft
where tfpft.trade_date =#{batchDate}
and tfpft.BUSI_TYPE = #{busiType}
and tfpft.PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

	and tfpft.FINPROD_TYPE2 = #{finProdType2}

delete from trd_product_deal tfpft
where tfpft.TOTLE_TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

	and FINPROD_TYPE2 = #{finProdType2}

)

delete from trd_product_deal_add tfpft
where tfpft.trade_id in (
	select tfpft.trade_id from trd_product_deal tfpft
	where tfpft.TOTLE_TRADE_ID in (
	select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
	where trade_date =#{batchDate}
	and BUSI_TYPE = #{busiType}
	and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
	and finprod_id =#{finprodId}

		and FINPROD_TYPE2 = #{finProdType2}

	)
)

delete from STL_PAY_ORDERS tfpft
where tfpft.TRADE_ID in (
select TOTLE_TRADE_ID from TRD_FIN_PRODUCT_DEAL_TOTAL
where trade_date =#{batchDate}
and BUSI_TYPE = #{busiType}
and PS in (#{PS_T07},#{PS_T08},#{PS_T09},#{PS_T39})
and finprod_id =#{finprodId}

	and FINPROD_TYPE2 = #{finProdType2}

)

mapper.select:
SELECT
cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
SUM(AMOUNT)/100 AMOUNT,
vDate,
mDate,
yield,
CALC_RULE
FROM (
SELECT
listagg(t5.CASH_TYPE, ',') within group ( order by t5.CASH_ID ) CASH_TYPE,
listagg(t5.CASH_ID, ',') within group ( order by t5.CASH_ID ) CASH_ID,
T1.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
pp.INVEST_YESORNO,
T1.FINPROD_ID,
T1.CDATE,
DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1,'11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT,
'${vDate}' vDate,
'${mDate}' mDate,
'${yield}' yield,
/*现金流支付规则.支付频率 付息周期*/ T4.PAY_CYCLE CALC_RULE
/*检索对象 组合持仓*/ FROM PTL_SEC_POSITION_RULE T1
/*left join 标的类金融产品*/ LEFT JOIN FIN_PRODUCT T2
/*on 组合持仓.金融产品代码 = 标的类金融产品.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
/*left join 现金流信息*/ LEFT JOIN FIN_CASH_INFO T3
/*on 标的类金融产品.金融产品代码 = 现金流信息.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
/*and 现金流信息.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
/*and 现金流信息.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
/*left join 现金流支付规则*/ LEFT JOIN FIN_CASH_PAY_RULE T4
/*on 现金流信息.现金流代码 = 现金流支付规则.现金流代码*/ ON T3.CASH_ID = T4.CASH_ID
/*and 生效日期 小于等于 传参.调整后计算结束日*/ AND T4.EFF_DATE <= #{adjustMDate}
LEFT JOIN FIN_CASH_PLAN T5 ON T1.FINPROD_ID = T5.FINPROD_ID AND T5.MDATE = #{adjustMDate}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
/*检索条件 金融产品代码 = 传参.金融产品代码*/ where T1.FINPROD_ID = #{finprodId}
/*and 持仓类型 = 数据字典缓存.持仓类型.实际*/

AND T1.HODING_TYPE = 'A_004'
/*and 组合持仓.日期 = 平台日*/ AND t1.CDATE < #{adjustMDate}
AND T1.SEC_ACCT_ID = #{secAcctId}
and T1.AMOUNT > 0
AND nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
AND NOT EXISTS (
SELECT 1 FROM PTL_SEC_POSITION_RULE tpsp
where tpsp.HODING_TYPE = T1.HODING_TYPE
and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
and tpsp.FINPROD_ID = T1.FINPROD_ID
and tpsp.CDATE > T1.CDATE
and tpsp.CDATE < #{adjustMDate}
)
/*不存在生效的交易*/
and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') = TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/
AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') >= TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
group by
pp.PORTFOLIO_NAME,
T1.PORTFOLIO_ID,
T1.FINPROD_ID,
PP.INVEST_YESORNO,
T1.CDATE,
T1.AMOUNT,
T1.HODING_TYPE,
T4.PAY_CYCLE
)
group by cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
CDATE,
vDate,
mDate,
yield,
CALC_RULE
having SUM(AMOUNT) > 0
